<?php declare(strict_types=1); use Kulturhus\Verein\Finance;
$financeCatalogueText=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\FinanceReceiptMessages::text($source,$financeFrameMessages??[],$values);
$ff=$ff??(isset($financeCatalogue)?\Kulturhus\Verein\Web\FinanceCatalogueFilters::read($_GET,$view,$tab):[]);if($view==='donations')$ff['kind']='donation';elseif($tab==='contributions')$ff['kind']='contribution';
$financeCatalogueFailed=false;
if(!isset($financeCatalogue)){try{$ff=\Kulturhus\Verein\Web\FinanceCatalogueFilters::read($_GET,$view,$tab);$financeCatalogue=$finance->entriesPage($ff,$_GET['page']??1,$_GET['sort']??'document_date',$_GET['order']??'desc',\Kulturhus\Verein\Web\FinanceCatalogueFilters::pageSize($_GET));}catch(DomainException$failure){$financeCatalogueFailed=true;$financeCatalogue=['rows'=>[],'total'=>0,'totals'=>['income'=>0,'expense'=>0,'allocated'=>0,'remaining'=>0,'net'=>0],'page'=>1,'pages'=>1,'sort'=>'document_date','order'=>'desc'];}}
$financeTotals=$financeCatalogue['totals'];$financeCount=$financeCatalogue['total'];$financePage=$financeCatalogue['page'];$financePages=$financeCatalogue['pages'];$financeSort=$financeCatalogue['sort'];$financeOrder=$financeCatalogue['order'];$visibleFinanceRows=$financeCatalogue['rows'];
if($financeCatalogueFailed){$financeSort=is_string($_GET['sort']??'document_date')?($_GET['sort']??'document_date'):'';$financeOrder=is_string($_GET['order']??'desc')?($_GET['order']??'desc'):'';}
$financeCatalogueChoice=static function(mixed $raw,array $allowed)use($financeCatalogueText):void{if($raw!==null&&(!is_string($raw)||!in_array($raw,$allowed,true))){$value=is_string($raw)?$raw:'';echo '<option selected value="'.e($value).'" data-finance-invalid-choice>'.e(is_string($raw)?$raw:$financeCatalogueText('Auswahl prüfen')).'</option>';}};
$financeListBase=['view'=>$view,'tab'=>$tab]+scalarFields($_GET,['kind','status','from','to','q','account','direction','sort','order','per_page']);
$columns=['kind'=>'Belegtyp','document_date'=>'Belegdatum','counterparty'=>'Name','description'=>'Bezeichnung','paid_on'=>'Zahlungsdatum'];
?>
<link rel="stylesheet" href="finance-catalogue.css?v=1">
<section id="finance-catalogue" class="content"><section class="card">
<form method="get" action="#finance-catalogue" class="form-grid"><?php foreach($financeListBase as$k=>$v)if(!in_array($k,['q','status'],true))echo hidden($k,$v); ?>
<label><?= e($financeCatalogueText('Belege durchsuchen')) ?><input class="form-control" id="finance-search" name="q" type="search" maxlength="150" value="<?= e(input($_GET,'q')) ?>"></label>
<label><?= e($financeCatalogueText('Belegstatus')) ?><select class="form-control" id="finance-status" name="status"><?php $financeCatalogueChoice($_GET['status']??null,['','archive','open','partial','paid','cancelled','reversed']); ?><option value=""><?= e($financeCatalogueText('Aktive Belege')) ?></option><?php foreach(['archive'=>'Archivierte / verworfene Belege','open'=>'Offen (inkl. Teilzahlung)','partial'=>'Teilbezahlt','paid'=>'Bezahlt','cancelled'=>'Verworfen','reversed'=>'Gegengebucht']as$k=>$v): ?><option value="<?= e($k) ?>" <?= input($_GET,'status')===$k?'selected':'' ?>><?= e($financeCatalogueText($v)) ?></option><?php endforeach ?></select></label>
<button class="btn btn-solid theme-primary"><?= e($financeCatalogueText('Belege suchen')) ?></button></form>
<details id="finance-filters" <?= $financeCatalogueFailed?'open':'' ?>><summary><?= e($financeCatalogueText('Weitere Filter')) ?></summary><form method="get" action="#finance-catalogue" class="form-grid">
<?= hidden('view',$view).hidden('tab',$tab).hidden('q',input($_GET,'q')).hidden('status',input($_GET,'status')).hidden('sort',$financeSort).hidden('order',$financeOrder).(array_key_exists('per_page',$financeListBase)?hidden('per_page',$financeListBase['per_page']):'') ?>
<?php if($view!=='donations'&&$tab!=='contributions'): ?><label><?= e($financeCatalogueText('Belegtyp')) ?><select class="form-control" name="kind"><?php $financeCatalogueChoice($_GET['kind']??null,['',...array_keys(Finance::KINDS)]); ?><option value=""><?= e($financeCatalogueText('Alle Belegtypen')) ?></option><?php foreach(Finance::KINDS as$k=>$v): ?><option value="<?= e($k) ?>" <?= input($_GET,'kind')===$k?'selected':'' ?>><?= e($financeCatalogueText($v)) ?></option><?php endforeach ?></select></label><?php endif ?>
<label><?= e($financeCatalogueText('Belegdatum von')) ?><input class="form-control" name="from" type="date" value="<?= e(input($_GET,'from')) ?>"></label><label><?= e($financeCatalogueText('Bis')) ?><input class="form-control" name="to" type="date" value="<?= e(input($_GET,'to')) ?>"></label>
<label><?= e($financeCatalogueText('Konto / Kasse')) ?><select class="form-control" name="account"><?php $financeCatalogueChoice($_GET['account']??null,['',...array_column($accountRows,'id')]); ?><option value=""><?= e($financeCatalogueText('Alle')) ?></option><?php foreach($accountRows as$a): ?><option value="<?= e($a['id']) ?>" <?= input($_GET,'account')===$a['id']?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach ?></select></label>
<label><?= e($financeCatalogueText('Zahlungsrichtung')) ?><select class="form-control" name="direction"><?php $financeCatalogueChoice($_GET['direction']??null,['','income','expense']); ?><option value=""><?= e($financeCatalogueText('Alle')) ?></option><option value="income" <?= input($_GET,'direction')==='income'?'selected':'' ?>><?= e($financeCatalogueText('Eingang')) ?></option><option value="expense" <?= input($_GET,'direction')==='expense'?'selected':'' ?>><?= e($financeCatalogueText('Ausgang')) ?></option></select></label>
<button class="btn btn-outline theme-secondary"><?= e($financeCatalogueText('Filter anwenden')) ?></button></form></details>
<details id="finance-columns" data-columns-panel hidden><summary><?= e($financeCatalogueText('Angaben auswählen')) ?></summary><div class="column-options"><?php foreach($columns as$k=>$label): ?><label class="check"><input class="check" type="checkbox" data-column="finance-<?= e($k) ?>" checked><?= e($financeCatalogueText($label)) ?></label><?php endforeach ?></div></details>
<form method="get" action="#finance-catalogue" class="form-grid"><?php foreach($financeListBase as$k=>$v)if(!in_array($k,['sort','order'],true))echo hidden($k,$v); ?>
<label><?= e($financeCatalogueText('Sortierung')) ?><select class="form-control" name="sort"><?php $financeCatalogueChoice($_GET['sort']??null,['document_date','number','counterparty','amount_cents']); ?><?php foreach(['document_date'=>'Belegdatum','number'=>'Nummer','counterparty'=>'Name','amount_cents'=>'Betrag']as$k=>$v): ?><option value="<?= e($k) ?>" <?= $financeSort===$k?'selected':'' ?>><?= e($financeCatalogueText($v)) ?></option><?php endforeach ?></select></label>
<label><?= e($financeCatalogueText('Reihenfolge')) ?><select class="form-control" name="order"><?php $financeCatalogueChoice($_GET['order']??null,['desc','asc']); ?><option value="desc" <?= $financeOrder==='desc'?'selected':'' ?>><?= e($financeCatalogueText('Absteigend')) ?></option><option value="asc" <?= $financeOrder==='asc'?'selected':'' ?>><?= e($financeCatalogueText('Aufsteigend')) ?></option></select></label><button class="btn btn-outline theme-secondary"><?= e($financeCatalogueText('Sortieren')) ?></button></form>
<form method="get" action="#finance-catalogue" class="form-grid" data-finance-page-size><?php foreach($financeListBase as$k=>$v)if($k!=='per_page')echo hidden($k,$v); ?><label><?= e($financeCatalogueText('Belege pro Seite')) ?><select class="form-control" name="per_page"><?php $financeCatalogueChoice(array_key_exists('per_page',$_GET)?($_GET['per_page']??[]):null,['6','20','40','100']);foreach(['6','20','40','100']as$catalogueSize): ?><option value="<?= e($catalogueSize) ?>" <?= (!array_key_exists('per_page',$_GET)&&$catalogueSize==='6')||(is_string($_GET['per_page']??null)&&$_GET['per_page']===$catalogueSize)?'selected':'' ?>><?= e($catalogueSize) ?></option><?php endforeach ?></select></label><button class="btn btn-outline theme-secondary"><?= e($financeCatalogueText('Anzahl anwenden')) ?></button></form>
<?php if(!$financeCatalogueFailed): ?><form method="post"><?= csrf().hidden('action','finance-export') ?><?php foreach($ff as$k=>$v)echo hidden($k,$v); ?><button class="btn btn-outline theme-secondary" aria-label="<?= e($financeCatalogueText('Gefilterte Finanzliste als CSV herunterladen')) ?>"><?= e($financeCatalogueText('CSV herunterladen')) ?></button></form><?php echo "\n";endif ?>
<?php if($financeCatalogueFailed): ?><p role="alert"><?= e($financeCatalogueText('Filter oder Seite korrigieren und erneut suchen.')) ?></p><form method="get" action="#finance-catalogue" class="finance-pages" data-finance-page-correction><?php foreach($financeListBase as$catalogueContextKey=>$catalogueContextValue)echo hidden($catalogueContextKey,$catalogueContextValue); ?><label><?= e($financeCatalogueText('Seite korrigieren')) ?><input class="form-control" name="page" type="text" inputmode="numeric" value="<?= e(is_string($_GET['page']??null)?$_GET['page']:'') ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($financeCatalogueText('Erneut anzeigen')) ?></button></form><?php else: ?><p data-finance-catalogue-summary><?= e($financeCatalogueText('{count} Belege · Seite {page} von {pages}',['count'=>(int)$financeCount,'page'=>(int)$financePage,'pages'=>(int)$financePages])) ?></p><?php endif ?>
<div class="finance-original-cards"><?php foreach($visibleFinanceRows as$r): ?><article class="finance-original-card" data-finance-original="<?= e($r['id']) ?>">
<header><a class="btn btn-outline theme-secondary receipt-number" href="<?= e(url($financeListBase+['page'=>$financePage,'entry'=>$r['id']])) ?>"><?= e($r['display_number']??sprintf('KH-%05d',$r['number'])) ?></a><span class="status <?= $r['payment_state']==='paid'?'aktiv':($r['payment_state']==='partial'?'passiv':'') ?>"><?= e($financeCatalogueText(paymentLabel($r['payment_state']))) ?></span></header>
<dl><div data-col="finance-kind"><dt><?= e($financeCatalogueText('Belegtyp')) ?></dt><dd><?= e($financeCatalogueText(Finance::KINDS[$r['kind']])) ?></dd></div><div data-col="finance-document_date"><dt><?= e($financeCatalogueText('Belegdatum')) ?></dt><dd><?= e(dateDe($r['document_date'])) ?></dd></div><div data-col="finance-counterparty"><dt><?= e($financeCatalogueText('Name')) ?></dt><dd><?= e($r['counterparty']) ?></dd></div><div data-col="finance-description"><dt><?= e($financeCatalogueText('Bezeichnung')) ?></dt><dd><?= e($r['description']) ?></dd></div><div data-col="finance-paid_on"><dt><?= e($financeCatalogueText('Zahlungsdatum')) ?></dt><dd><?= e(dateDe($r['paid_on'])) ?></dd></div><div><dt><?= e($financeCatalogueText('Betrag (Brutto)')) ?></dt><dd><?= e(euro((int)$r['amount_cents'])) ?></dd></div><?php if(!in_array($r['payment_state'],['cancelled','reversed'],true)): ?><div data-finance-payment="allocated"><dt><?= e($financeCatalogueText('Bereits zugeordnet')) ?></dt><dd data-finance-allocated><?= e(euro((int)$r['allocated_cents'])) ?></dd></div><div data-finance-payment="remaining"><dt><?= e($financeCatalogueText('Noch offen')) ?></dt><dd data-finance-remaining><?= e(euro((int)$r['remaining_cents'])) ?></dd></div><?php endif ?></dl><?php if(in_array($r['payment_state'],['cancelled','reversed'],true)): ?><p data-finance-inactive><?= e($financeCatalogueText('Dieser Beleg ist nicht mehr für Zahlungen offen.')) ?></p><?php endif;echo "\n"; ?>
</article><?php endforeach;if(!$visibleFinanceRows&&!$financeCatalogueFailed): ?><p><?= e($financeCatalogueText('Keine Belege gefunden.')) ?></p><?php endif ?></div>
<?php if(!$financeCatalogueFailed): ?>
<nav class="finance-pages" aria-label="<?= e($financeCatalogueText('Belegseiten')) ?>"><?php foreach([-1=>'Vorherige',1=>'Nächste']as$delta=>$label)if($financePage+$delta>=1&&$financePage+$delta<=$financePages): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($financeListBase+['page'=>$financePage+$delta])) ?>#finance-catalogue"><?= e($financeCatalogueText($label)) ?></a><?php endif ?></nav>
<form method="get" action="#finance-catalogue" class="finance-pages"><?php foreach($financeListBase as$k=>$v)echo hidden($k,$v); ?><label><?= e($financeCatalogueText('Seite')) ?><input class="form-control" type="number" name="page" min="1" max="<?= (int)$financePages ?>" value="<?= (int)$financePage ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($financeCatalogueText('Seite anzeigen')) ?></button></form>
<dl class="finance-filter-totals" aria-label="<?= e($financeCatalogueText('Summen aller gefilterten Belege')) ?>"><?php foreach(['income'=>'Einnahmen','expense'=>'Ausgaben','remaining'=>'Noch offen','net'=>'Summe']as$key=>$label): ?><div><dt><?= e($financeCatalogueText($label)) ?></dt><dd data-finance-total="<?= e($key) ?>"><?= e(euro($financeTotals[$key])) ?></dd></div><?php endforeach ?></dl>
<?php endif ?></section></section>
